const fs = require("fs");
const path = require("path");

const root = __dirname;

function read(name) {
  return fs.readFileSync(path.join(root, name), "utf8");
}

const icons = read("icons.js")
  .replace(/\bexport\s+function\s+icon\b/, "function icon");

const api = read("api.js")
  .replace(/\bexport\s+class\s+/g, "class ")
  .replace(/\bexport\s+function\s+/g, "function ")
  .replace(/\nexport\s+\{\s*DEFAULT_API_BASE\s*\};?\s*$/m, "");

const app = read("app.js")
  .replace(/^import\s+.*?;\s*$/gm, "");

const bundle = [
  "/* Generated by build.cjs. Edit icons.js, api.js, or app.js, then rebuild. */",
  "(() => {",
  '"use strict";',
  icons,
  api,
  app,
  "})();",
  "",
].join("\n");

fs.writeFileSync(path.join(root, "bundle.js"), bundle, "utf8");
console.log(`bundle.js generated (${Buffer.byteLength(bundle)} bytes)`);
